import Foundation

/// What each AstraGram setting does, shown on a long press on its row. Keyed by the row's stable ID in
/// `AstraGramSettingsController` (`AstraGramSettingsEntry.stableId`); a row without an entry has no description.
extension AstraStrings {
    func featureDescription(_ id: Int32) -> String? {
        let ru = self.isRussian
